#!/usr/bin/env node
// Task-local script: fetch contacts from the email API using only built-in Node.js
// (global fetch). No external dependencies required.

const args = process.argv.slice(2);
function argValue(name) {
  const idx = args.indexOf(name);
  return idx !== -1 && args[idx + 1] ? args[idx + 1] : undefined;
}

const apiKey = argValue('--api-key');
const userEmail = argValue('--user-email');
const baseUrls = [
  process.env.EMAIL_API_BASE_URL,
  'https://agenskill-api.onrender.com', // default per skill manifest
  'https://agenskill.onrender.com'      // default per helper scripts
].filter(Boolean);

if (!apiKey || !userEmail) {
  console.error(JSON.stringify({ success: false, error: 'Missing --api-key or --user-email' }, null, 2));
  process.exit(1);
}

async function tryBaseUrl(baseUrl) {
  const url = `${baseUrl}/contacts`;
  const response = await fetch(url, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}: ${data.error || 'unknown error'}`);
  }
  return {
    baseUrl,
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

(async () => {
  let lastError = null;
  for (const baseUrl of baseUrls) {
    try {
      const result = await tryBaseUrl(baseUrl);
      console.log(JSON.stringify(result, null, 2));
      process.exit(0);
    } catch (err) {
      lastError = err;
    }
  }
  console.error(JSON.stringify({ success: false, error: `All base URLs failed: ${lastError ? lastError.message : 'unknown'}` }, null, 2));
  process.exit(1);
})();

#!/usr/bin/env node
// Task-local diagnostic: check reachability of candidate API base URLs
// (health endpoint and contacts endpoint). Uses only built-in Node.js.

const baseUrls = [
  process.env.EMAIL_API_BASE_URL,
  'https://agenskill-api.onrender.com',
  'https://agenskill.onrender.com',
  'https://CERT-5586b2a458a23fb1.onrender.com'
].filter(Boolean);

async function probe(baseUrl, path, headers) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 15000);
    const response = await fetch(`${baseUrl}${path}`, { headers, signal: controller.signal });
    clearTimeout(timer);
    const text = await response.text();
    return { ok: response.ok, status: response.status, body: text.slice(0, 500) };
  } catch (err) {
    return { ok: false, error: err.message, cause: err.cause ? err.cause.message : null };
  }
}

(async () => {
  const results = [];
  for (const baseUrl of baseUrls) {
    const health = await probe(baseUrl, '/health');
    results.push({ baseUrl, health });
  }
  console.log(JSON.stringify(results, null, 2));
})();

